SELECT 'batch_006_9fe5b934_wav_12' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1dd2c3ea-51a','sm-upload-45c17eb9-747','sm-upload-52918a7d-d0d','sm-upload-55d617d1-946','sm-upload-59b1f46e-a95','sm-upload-6175a166-606','sm-upload-7bdaf28e-f9e','sm-upload-ba3fca4b-62d','sm-upload-ce7ca9dd-629','sm-upload-e424797b-1e7','sm-upload-f5f11cb1-5e6','sm-upload-fac12da8-c8b') AND album_id='al-4c9a3a416c2c4378a9c451729fe5b934') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1dd2c3ea-51a','sm-upload-45c17eb9-747','sm-upload-52918a7d-d0d','sm-upload-55d617d1-946','sm-upload-59b1f46e-a95','sm-upload-6175a166-606','sm-upload-7bdaf28e-f9e','sm-upload-ba3fca4b-62d','sm-upload-ce7ca9dd-629','sm-upload-e424797b-1e7','sm-upload-f5f11cb1-5e6','sm-upload-fac12da8-c8b') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-4c9a3a416c2c4378a9c451729fe5b934' AND name='旧未来ЯEMIXTION') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-4c9a3a416c2c4378a9c451729fe5b934') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-4c9a3a416c2c4378a9c451729fe5b934') AS calculated_size;
